import type { Racket } from "@/types/product";

/**
 * Media conventions. Product renders and models are generated by
 * `scripts/blender/build_rackets.py` from each racket's real specs.
 */

export type RenderView = "hero" | "front" | "detail";

export function renderSrc(slug: string, view: RenderView = "hero") {
  return `/products/${slug}-${view}.webp`;
}

export function modelSrc(slug: string) {
  return `/models/${slug}.glb`;
}

/** Best available still for a racket: licensed photo if present, else the representative render. */
export function productStill(r: Racket, view: RenderView = "hero") {
  return r.image && view === "hero" ? { src: r.image, kind: "photo" as const } : { src: renderSrc(r.slug, view), kind: "render" as const };
}

export const STUDIO_MODEL = modelSrc("studio");
